<?php
/**
 * RKDF University — Helper Functions
 */

/**
 * Generate absolute site URL
 */
function url(string $path = ''): string {
    if (empty($path) || $path === '/') {
        return BASE_PATH;
    }
    if (str_starts_with($path, 'http://') || str_starts_with($path, 'https://') || str_starts_with($path, '#') || str_starts_with($path, 'tel:') || str_starts_with($path, 'mailto:') || str_starts_with($path, 'javascript:')) {
        return $path;
    }
    return BASE_PATH . ltrim($path, '/');
}

/**
 * Get current page filename or request path
 */
function current_page(): string {
    return basename($_SERVER['PHP_SELF'] ?? '');
}

/**
 * Check if a nav link is active
 */
function is_active(string $path): bool {
    $currentUri = parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH) ?? '';
    $targetUrl  = url($path);
    $targetUri  = parse_url($targetUrl, PHP_URL_PATH) ?? '';
    
    $cleanCurrent = trim($currentUri, '/');
    $cleanTarget  = trim($targetUri, '/');

    if ($cleanCurrent !== '' && $cleanCurrent === $cleanTarget) {
        return true;
    }
    $cleanCurrentNoIndex = preg_replace('/(\/|^)index\.php$/', '', $cleanCurrent);
    $cleanTargetNoIndex  = preg_replace('/(\/|^)index\.php$/', '', $cleanTarget);
    if ($cleanCurrentNoIndex !== '' && $cleanCurrentNoIndex === $cleanTargetNoIndex) {
        return true;
    }
    // Fallback: file match
    $currentFile = basename($_SERVER['PHP_SELF'] ?? '');
    $targetFile = basename($path);
    if ($currentFile === $targetFile && $currentFile !== '' && $currentFile !== 'index.php') {
        return true;
    }
    return false;
}

/**
 * Render active class
 */
function nav_class(string $href): string {
    return is_active($href) ? ' active text-foreground font-semibold' : '';
}

/**
 * Safely escape HTML
 */
function e(string $str): string {
    return htmlspecialchars($str, ENT_QUOTES, 'UTF-8');
}

/**
 * Generate asset URL
 */
function asset(string $path): string {
    return ASSETS_PATH . ltrim($path, '/');
}

/**
 * Generate image URL
 */
function img(string $filename): string {
    return asset('images/' . $filename);
}

